/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Exports
 *   Functions: App
 * Internal
 *   Types: View, Skin
 *   Functions: initialSkin
 *   Constants: SKIN_STORAGE_KEY
 * @end-catalog */

import {useCallback, useEffect, useRef, useState} from 'react';
import {Archive, BookOpen, Flame, Palette, PlusCircle, X} from 'lucide-react';
import {AccountMenu} from './components/AccountMenu';
import {ChromeGuide} from './components/ChromeGuide';
import {ExtensionGuide} from './components/ExtensionGuide';
import {History} from './components/History';
import {NewResearch} from './components/NewResearch';
import {RecordsView} from './components/RecordsView';
import {ReportView} from './components/ReportView';
import {RunDetail} from './components/RunDetail';
import {api} from './lib/api';
import {AppSettings, ChromeConnectionStatus, ResearchPreferences, ResearchRequest, RunManifest} from './types';
import {SaveOptions} from './hooks/useAutoSave';

type View = 'new' | 'guide' | 'history' | 'run' | 'report' | 'records';
type Skin = 'classic' | 'shinobi';

const SKIN_STORAGE_KEY = 'naruto-research-skin';

const initialSkin = (): Skin => {
  const forced = new URLSearchParams(window.location.search).get('skin');
  if (forced === 'classic' || forced === 'shinobi') return forced;
  const saved = window.localStorage.getItem(SKIN_STORAGE_KEY);
  return saved === 'shinobi' ? 'shinobi' : 'classic';
};

export default function App() {
  const [settings, setSettings] = useState<AppSettings>();
  // The form choices confirmed on disk; settings.defaults also holds choices whose save is in flight or failed.
  const [savedDefaults, setSavedDefaults] = useState<AppSettings['defaults']>();
  const [runs, setRuns] = useState<RunManifest[]>([]);
  const [view, setView] = useState<View>('new');
  const viewRef = useRef(view);
  viewRef.current = view;
  const [selected, setSelected] = useState<RunManifest>();
  const [busy, setBusy] = useState(false);
  const [selectingDataRoot, setSelectingDataRoot] = useState(false);
  const [chromeStatus, setChromeStatus] = useState<ChromeConnectionStatus>();
  const [connectingChrome, setConnectingChrome] = useState(false);
  const [error, setError] = useState('');
  const [skin, setSkin] = useState<Skin>(initialSkin);
  const settingsGeneration = useRef(0);
  const refreshSettings = useCallback(async () => {
    const generation = ++settingsGeneration.current;
    const next = await api.settings();
    if (generation === settingsGeneration.current) {
      setSettings(next);
      setSavedDefaults(next.defaults);
    }
  }, []);

  const loadRuns = useCallback(() => api.listRuns().then(setRuns).catch((reason) => setError(reason.message)), []);
  useEffect(() => {
    void refreshSettings().catch((reason) => setError(reason.message));
    void loadRuns();
  }, [loadRuns, refreshSettings]);
  useEffect(() => {
    if (import.meta.env.MODE !== 'hosted') return;
    const changed = () => {
      // Remove the prior displayed identity before resolving the shared cookie session.
      settingsGeneration.current += 1;
      setSettings((current) => current?.analysis ? {...current, analysis: {...current.analysis,
        account: undefined, aiConfigured: false, loginRequired: true}} : current);
      void refreshSettings().catch((reason) => setError(reason.message));
    };
    window.addEventListener('naruto:analysis-account-change', changed);
    return () => window.removeEventListener('naruto:analysis-account-change', changed);
  }, [refreshSettings]);
  useEffect(() => {
    let active = true;
    const refresh = () => api.chromeStatus()
      .then((status) => { if (active) setChromeStatus(status); })
      .catch((reason) => { if (active) setError(reason.message); });
    void refresh();
    const timer = window.setInterval(() => void refresh(), 1_500);
    return () => {
      active = false;
      window.clearInterval(timer);
    };
  }, []);
  useEffect(() => {
    window.scrollTo({top: 0, left: 0, behavior: 'auto'});
  }, [view]);
  useEffect(() => {
    window.localStorage.setItem(SKIN_STORAGE_KEY, skin);
    document.documentElement.dataset.skin = skin;
    const themeColor = document.querySelector('meta[name="theme-color"]');
    themeColor?.setAttribute('content', skin === 'shinobi' ? '#0b1821' : '#15130f');
  }, [skin]);

  const start = async (request: ResearchRequest) => {
    setBusy(true);
    setError('');
    try {
      const run = await api.startRun(request);
      setSelected(run);
      setView('run');
      await loadRuns();
    } catch (reason) {
      setError(reason instanceof Error ? reason.message : String(reason));
      void refreshSettings().catch(() => undefined);
    } finally {
      setBusy(false);
    }
  };

  const openRun = (run: RunManifest) => {
    setSelected(run);
    setView(run.reportReady ? 'report' : 'run');
  };

  const browseRecords = (run: RunManifest) => {
    if ((settings?.apiVersion ?? 0) < 7) {
      setError('后台仍在运行旧版本。请关闭当前工具后重新双击启动，再浏览完整记录。');
      return;
    }
    setSelected(run);
    setView('records');
  };

  const openRunFolder = (run: RunManifest) => {
    void api.openFolder(run.id).catch((reason) => setError(reason instanceof Error ? reason.message : String(reason)));
  };

  const importRun = async (file: File) => {
    const run = await api.importRun(file);
    setRuns((current) => [run, ...current.filter((item) => item.id !== run.id)]);
    return run;
  };

  const deleteRun = async (run: RunManifest) => {
    await api.deleteRun(run.id);
    setRuns((current) => current.filter((item) => item.id !== run.id));
    setSelected((current) => current?.id === run.id ? undefined : current);
  };

  const openChromeSettings = async () => {
    setError('');
    try {
      await api.openChromeSettings();
    } catch (reason) {
      setError(reason instanceof Error ? reason.message : String(reason));
      throw reason;
    }
  };

  const connectChrome = async () => {
    if (chromeStatus?.state === 'disconnecting') return;
    if (settings?.runtime !== 'browser' && !chromeStatus?.remoteDebuggingEnabled) {
      setView('guide');
      await openChromeSettings();
      return;
    }
    setConnectingChrome(true);
    setError('');
    // Re-checking an already connected Chrome only refreshes the B站 account, so it keeps the connected status.
    const recheck = chromeStatus?.state === 'connected' && chromeStatus.connected;
    try {
      if (!recheck) setChromeStatus((current) => current ? {...current, state: 'connecting', message: settings?.runtime === 'browser'
        ? '正在连接扩展并检查 B站登录状态，请稍候。' : '正在请求连接，请在 Chrome 弹窗中点击“允许”。'} : current);
      setChromeStatus(await api.connectChrome());
    } catch (reason) {
      setError(reason instanceof Error ? reason.message : String(reason));
      setChromeStatus(await api.chromeStatus().catch(() => chromeStatus));
    } finally {
      setConnectingChrome(false);
    }
  };

  const disconnectChrome = async () => {
    setError('');
    try {
      setChromeStatus((current) => current ? {
        ...current,
        state: 'disconnecting',
        message: '正在安全断开 Chrome，请稍候。'
      } : current);
      setChromeStatus(await api.disconnectChrome());
    } catch (reason) {
      setError(reason instanceof Error ? reason.message : String(reason));
      setChromeStatus(await api.chromeStatus().catch(() => chromeStatus));
    }
  };

  const selectDataRoot = async () => {
    setSelectingDataRoot(true);
    setError('');
    try {
      const result = await api.selectDataRoot();
      if (result.cancelled) return;
      setSettings((current) => current ? {...current, dataRoot: result.dataRoot} : current);
      setSelected(undefined);
      setView('new');
      await loadRuns();
    } catch (reason) {
      setError(reason instanceof Error ? reason.message : String(reason));
    } finally {
      setSelectingDataRoot(false);
    }
  };

  const loginAnalysis = async (identifier: string, password: string) => {
    setError('');
    await api.loginAnalysis(identifier, password);
    await refreshSettings();
  };

  const logoutAnalysis = async () => {
    setError('');
    await api.logoutAnalysis();
    await refreshSettings();
  };

  const savePreferences = async (changes: ResearchPreferences, options?: SaveOptions) => {
    // Shown at once, so returning to the form while the save is in flight shows the new choices; a reopened
    // form compares with savedDefaults, so it saves them again if this save does not succeed.
    setSettings((current) => current ? {...current, defaults: {...current.defaults, ...changes}} : current);
    // A desktop server older than API 12 can only remember keywords; the other choices then last for this visit.
    const legacy = settings?.runtime !== 'browser' && (settings?.apiVersion ?? 0) < 12;
    try {
      if (legacy) {
        if (changes.keywords !== undefined) {
          const saved = await api.saveKeywords({keywords: changes.keywords, useKeywordPrefix: changes.useKeywordPrefix ?? true});
          setSavedDefaults((current) => current ? {...current, ...saved} : current);
        }
        return;
      }
      const saved = await api.savePreferences(changes, options);
      setSettings((current) => current ? {...current, defaults: {...current.defaults, ...saved}} : current);
      setSavedDefaults((current) => current ? {...current, ...saved} : current);
    } catch (reason) {
      // The form shows its own message; once the user has left it, nothing else would.
      if (viewRef.current !== 'new') setError(`设置未能保存在本机：${reason instanceof Error ? reason.message : String(reason)}`);
      throw reason;
    }
  };

  if (!settings) return <div className="app-loading"><Flame className="brand-flame"/><strong>正在打开本地调查数据…</strong>{error && <p role="alert">{error}</p>}</div>;

  return (
    <div className={`app-shell skin-${skin}`} data-skin={skin}>
      <header className="topbar">
        <button className="brand" onClick={() => setView('new')}><span><Flame/></span><div><strong>火影手游</strong><small>玩家反馈调查工具</small></div></button>
        <nav>
          <button className={view === 'new' ? 'active' : ''} onClick={() => setView('new')}><PlusCircle/>新建调查</button>
          <button className={`guide-nav ${view === 'guide' ? 'active' : ''}`} onClick={() => setView('guide')}><BookOpen/><span className="guide-nav-label"><b>{settings.runtime === 'browser' ? '扩展 ' : 'Chrome '}</b>教程</span><span className="guide-nav-badge">首次必看</span></button>
          <button className={view === 'history' ? 'active' : ''} onClick={() => {void loadRuns(); setView('history');}}><Archive/>历史调查{runs.length > 0 && <i>{runs.length}</i>}</button>
        </nav>
        <div className="topbar-tools">
          <label className="skin-picker">
            <Palette aria-hidden="true"/>
            <span>皮肤</span>
            <select aria-label="界面皮肤" value={skin} onChange={(event) => setSkin(event.target.value as Skin)}>
              <option value="classic">经典</option>
              <option value="shinobi">忍者密卷</option>
            </select>
          </label>
          <div className="local-pill" title={settings.runtime === 'browser' ? '数据在本机' : '本地运行'}><span/>{settings.runtime === 'browser' ? '数据在本机' : '本地运行'}</div>
          <AccountMenu analysis={settings.analysis} onLogout={logoutAnalysis}/>
        </div>
      </header>

      {view === 'new' && (
        <NewResearch settings={settings} chromeStatus={chromeStatus} connectingChrome={connectingChrome} busy={busy} selectingDataRoot={selectingDataRoot} onStart={start} onSelectDataRoot={selectDataRoot} onSavePreferences={savePreferences} savedDefaults={savedDefaults} onLoginAnalysis={loginAnalysis} onOpenGuide={() => setView('guide')} onConnectChrome={connectChrome} onDisconnectChrome={disconnectChrome}/>
      )}
      {view === 'guide' && settings.runtime === 'browser' && (
        <ExtensionGuide chromeStatus={chromeStatus} connectingChrome={connectingChrome} onBack={() => setView('new')} onConnectChrome={connectChrome} onDisconnectChrome={disconnectChrome}/>
      )}
      {view === 'guide' && settings.runtime !== 'browser' && (
        <ChromeGuide chromeSettingsSupported={(settings.apiVersion ?? 0) >= 6} chromeStatus={chromeStatus} connectingChrome={connectingChrome} onBack={() => setView('new')} onOpenChromeSettings={openChromeSettings} onConnectChrome={connectChrome} onDisconnectChrome={disconnectChrome}/>
      )}
      {view === 'history' && (
        <History runs={runs} browserRuntime={settings.runtime === 'browser'} archiveSupported={(settings.apiVersion ?? 0) >= 11} onOpen={openRun} onBrowse={browseRecords} onOpenFolder={openRunFolder} onImport={importRun} onExport={(run) => api.exportRun(run.id)} onDelete={deleteRun}/>
      )}
      {view === 'run' && selected && (
        <RunDetail initial={selected} onBack={() => {void loadRuns(); setView('history');}} onReport={(run) => {setSelected(run); setView('report');}} onError={setError}/>
      )}
      {view === 'report' && selected && (
        <ReportView run={selected} onBack={() => setView('run')} onError={setError}/>
      )}
      {view === 'records' && selected && (
        <RecordsView run={selected} onBack={() => {void loadRuns(); setView('history');}} onError={setError}/>
      )}

      {error && <div className="toast" role="alert"><span>{error}</span><button aria-label="关闭提示" onClick={() => setError('')}><X/></button></div>}
    </div>
  );
}
